-- F831 · atrasados no caso (ordem do Paulo de 27.11.2026). Só acrescenta; nada se apaga.
-- 1 · casos ganha a DIP, a citação, a ciência da decisão indeferitória definitiva (decadência do art. 103 da
--     Lei 8.213/91) e o jsonb `calculo` (RMI, reajustes, Tema 1124 e o último resultado da calculadora).
-- 2 · indices_mensais: as séries oficiais do Banco Central (SGS) que a calculadora usa, uma linha por
--     competência AAAA-MM. Os juros da poupança saem de (1 + rendimento) / (1 + TR) - 1, no navegador.
--     A carga inicial abaixo foi baixada do SGS em 27.11.2026; a renovação é semanal, pelo pg_net (como a F384).
--     Lê quem é colaborador ativo; ninguém grava pelo navegador (sem política de escrita).
alter table public.casos add column if not exists dip date;
alter table public.casos add column if not exists citado_em date;
alter table public.casos add column if not exists ciencia_indeferimento_em date;
alter table public.casos add column if not exists calculo jsonb;

create table if not exists public.indices_mensais (
  serie text not null check (serie in ('inpc','selic','tr','poup_antiga','poup_nova')),
  competencia text not null check (competencia ~ '^[0-9]{4}-[0-9]{2}$'),
  valor numeric not null,
  fonte text not null,
  baixado_em date not null default current_date,
  primary key (serie, competencia)
);
alter table public.indices_mensais enable row level security;
drop policy if exists indices_ler on public.indices_mensais;
create policy indices_ler on public.indices_mensais for select to authenticated using ((select sou_ativo()));
drop policy if exists so_colaborador_ativo on public.indices_mensais;
create policy so_colaborador_ativo on public.indices_mensais as restrictive for all to authenticated
  using ((select sou_ativo())) with check ((select sou_ativo()));
revoke insert, update, delete on public.indices_mensais from anon, authenticated;

-- a renovação: pede as séries (as diárias numa janela de dois anos, o limite do SGS é dez) e grava meia hora depois
create or replace function public.indices_pedir() returns void language plpgsql security definer set search_path to 'public' as $$
declare b text := 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.';
        d text := to_char((now() at time zone 'America/Sao_Paulo') - interval '2 years', '"01/"MM/YYYY');
        p jsonb := '{}';
begin
  p := p || jsonb_build_object('inpc', net.http_get(b || '188/dados?formato=json&dataInicial=' || d, timeout_milliseconds := 30000));
  p := p || jsonb_build_object('selic', net.http_get(b || '4390/dados?formato=json&dataInicial=' || d, timeout_milliseconds := 30000));
  p := p || jsonb_build_object('tr', net.http_get(b || '7811/dados?formato=json&dataInicial=' || d, timeout_milliseconds := 30000));
  p := p || jsonb_build_object('poup_nova', net.http_get(b || '195/dados?formato=json&dataInicial=' || d, timeout_milliseconds := 30000));
  on conflict (chave) do update set valor = excluded.valor;
end $$;

create or replace function public.indices_gravar() returns void language plpgsql security definer set search_path to 'public' as $$
declare r record; c text;
        fonte jsonb := '{"inpc":"INPC mensal (IBGE), SGS 188 do Banco Central","selic":"Selic acumulada no mês, SGS 4390 do Banco Central",
                         "tr":"TR do primeiro dia do mês, SGS 7811 do Banco Central",
                         "poup_nova":"Poupança a partir de 04/05/2012, rendimento no aniversário do dia 1º, SGS 195 do Banco Central"}';
begin
  for r in select key as serie, value::bigint as id from jsonb_each_text((select valor::jsonb from config_app where chave = 'indices_pedidos')) loop
    select content into c from net._http_response where id = r.id and status_code = 200;
    if c is null or left(c, 1) <> '[' then continue; end if;
    select r.serie, substr(e->>'data', 7, 4) || '-' || substr(e->>'data', 4, 2), (e->>'valor')::numeric, fonte->>r.serie,
           (now() at time zone 'America/Sao_Paulo')::date
      from json_array_elements(c::json) e
     where left(e->>'data', 2) = '01'   -- nas diárias, o aniversário do dia 1º; nas mensais, a própria competência
    on conflict (serie, competencia) do update set valor = excluded.valor, fonte = excluded.fonte, baixado_em = excluded.baixado_em;
  end loop;
end $$;

revoke all on function public.indices_pedir() from public, anon, authenticated;
revoke all on function public.indices_gravar() from public, anon, authenticated;
select cron.schedule('indices-pedir', '0 13 * * 1', 'select public.indices_pedir()');
select cron.schedule('indices-gravar', '30 13 * * 1', 'select public.indices_gravar()');

-- carga inicial (SGS, baixado em 27.11.2026)
on conflict (serie, competencia) do nothing;
